"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[632],{2632:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new dynamic raycast tree.","params":[{"name":"config","desc":"`aabb_padding` defaults to `0.05`. Larger padding absorbs more movement without a refit, at the cost of looser queries.","lua_type":"{ aabb_padding: number? }?"}],"returns":[{"desc":"","lua_type":"RaycastDynamic"}],"function_type":"static","source":{"line":33,"path":"docs/RaycastDynamic.lua"}},{"name":"Insert","desc":"Inserts a proxy into the tree. The shape and CFrame are read from the part\\nunless an explicit shape is given.\\n\\nErrors if `instance` is already inserted.","params":[{"name":"instance","desc":"","lua_type":"BasePart"},{"name":"shape","desc":"Overrides the shape derived from `instance`.","lua_type":"Shape?"},{"name":"cframe","desc":"Overrides `instance.CFrame` as the initial transform.","lua_type":"CFrame?"}],"returns":[],"function_type":"method","source":{"line":45,"path":"docs/RaycastDynamic.lua"}},{"name":"Remove","desc":"Removes a proxy from the tree. No-ops if `instance` was never inserted.","params":[{"name":"instance","desc":"","lua_type":"Instance"}],"returns":[],"function_type":"method","source":{"line":52,"path":"docs/RaycastDynamic.lua"}},{"name":"Move","desc":"Re-syncs a proxy to its part\'s current CFrame (shape unchanged). Pass an\\nexplicit CFrame to move it somewhere other than the part\'s live transform.\\n\\nIf the new position still fits inside the leaf\'s padded AABB, this is an\\nO(1) update. Otherwise the leaf is removed and reinserted.","params":[{"name":"instance","desc":"","lua_type":"BasePart"},{"name":"cframe","desc":"","lua_type":"CFrame?"}],"returns":[],"function_type":"method","source":{"line":64,"path":"docs/RaycastDynamic.lua"}},{"name":"UpdateTransform","desc":"Re-syncs a proxy to its part\'s current size and CFrame, rebuilding the\\nshape at the new scale using the same axis conventions as `from_part`.\\nPass explicit `cframe`/`size` to override.","params":[{"name":"instance","desc":"","lua_type":"BasePart"},{"name":"cframe","desc":"","lua_type":"CFrame?"},{"name":"size","desc":"","lua_type":"Vector3?"}],"returns":[],"function_type":"method","source":{"line":75,"path":"docs/RaycastDynamic.lua"}},{"name":"Rebuild","desc":"Forces a full SAH rebuild of the tree, restoring query quality after\\nheavy movement or insertion churn.\\n\\n```lua\\nRC:Rebuild()\\n```","params":[],"returns":[],"function_type":"method","source":{"line":85,"path":"docs/RaycastDynamic.lua"}},{"name":"Clear","desc":"Removes every proxy and resets internal state.","params":[],"returns":[],"function_type":"method","source":{"line":90,"path":"docs/RaycastDynamic.lua"}},{"name":"Raycast","desc":"Returns the nearest hit along the segment `origin -> origin + direction`,\\nor `nil` if nothing was hit.\\n\\n`direction` is the raw displacement vector, not a unit vector \u2014 its\\nmagnitude is the cast distance, matching `workspace:Raycast`.\\n\\nProxies the ray originates inside are ignored, matching native\\n`workspace:Raycast` semantics.","params":[{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"direction","desc":"","lua_type":"Vector3"},{"name":"filter","desc":"Return `false` to exclude a proxy from consideration.","lua_type":"((instance: Instance) -> boolean)?"}],"returns":[{"desc":"","lua_type":"RaycastResult?"}],"function_type":"method","source":{"line":107,"path":"docs/RaycastDynamic.lua"}}],"properties":[],"types":[],"name":"RaycastDynamic","desc":"Broadphase + narrow-phase raycasting against proxies that can move after\\ninsertion.\\n\\nInsertion picks the sibling that minimizes surface-area cost. Movement is\\nincremental: a small move is absorbed into the leaf\'s padded AABB with no\\ntree change, and a move outside that padding triggers a remove/reinsert.\\nHeavy churn loosens the tree\'s balance over time \u2014 call [RaycastDynamic:Rebuild]\\nperiodically to restore query quality.\\n\\n```lua\\nlocal Leyr = require(ReplicatedStorage.Leyr)\\n\\nlocal RC = Leyr.RaycastDynamic.new()\\nRC:Insert(workspace.Wall)\\n\\nlocal hit = RC:Raycast(origin, direction)\\nif hit then\\n    print(hit.Instance.Name, hit.Position)\\nend\\n```","source":{"line":25,"path":"docs/RaycastDynamic.lua"}}')}}]);